using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class RefreshTokenRepository(ProjetoIntegradorBackDbContext context):IRefreshTokenRepository{
public async Task<Result<RefreshToken>> ObterPorTokenAsync(string token,CancellationToken ct=default){try{var e=await context.RefreshTokens.Include(x=>x.Usuario).FirstOrDefaultAsync(x=>x.Token==token,ct);return e==null?Result<RefreshToken>.AsFailure(new Failure(404,"Refresh token não encontrado.")):Result<RefreshToken>.AsSuccess(e);}catch(Exception ex){return Result<RefreshToken>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<RefreshToken>> AdicionarAsync(RefreshToken e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();e.CriadoEm=DateTime.UtcNow;await context.RefreshTokens.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<RefreshToken>.AsSuccess(e);}catch(Exception ex){return Result<RefreshToken>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<string>> RevogarAsync(string token,CancellationToken ct=default){try{var e=await context.RefreshTokens.FirstOrDefaultAsync(x=>x.Token==token,ct);if(e==null)return Result<string>.AsFailure(new Failure(404,"Refresh token não encontrado."));e.Revogado=true;await context.SaveChangesAsync(ct);return Result<string>.AsSuccess("Refresh token revogado com sucesso.");}catch(Exception ex){return Result<string>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<string>> RevogarTodosDoUsuarioAsync(Guid id,CancellationToken ct=default){try{var es=await context.RefreshTokens.Where(x=>x.UsuarioId==id&&!x.Revogado).ToListAsync(ct);es.ForEach(x=>x.Revogado=true);await context.SaveChangesAsync(ct);return Result<string>.AsSuccess("Todos os refresh tokens revogados.");}catch(Exception ex){return Result<string>.AsFailure(new Failure(500,ex.Message));}}}